```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ifstream plik("transakcje.txt");
    int saldo = 500;
    int maxSaldo = saldo;
    vector<int> debety;
    char typ;
    int kwota;
    int nr = 0;

    cout << "a) Symulacja:" << endl;
    while (plik >> typ >> kwota) {
        nr++;
        if (typ == 'W') saldo += kwota;
        else saldo -= kwota;
        cout << "   Transakcja " << nr << ": " << typ << " " << kwota << " -> saldo: " << saldo << endl;
        if (saldo < 0) debety.push_back(nr);
        if (saldo > maxSaldo) maxSaldo = saldo;
    }

    cout << endl << "b) Debet po transakcjach: ";
    for (int i = 0; i < (int)debety.size(); i++) {
        if (i > 0) cout << ", ";
        cout << debety[i];
    }
    cout << endl;

    cout << endl << "c) Saldo koncowe: " << saldo << endl;
    cout << "   Saldo maksymalne: " << maxSaldo << endl;
    return 0;
}
```

Weryfikacja (saldo startowe = 500):
1. W 200: 500+200 = 700 (max=700)
2. P 400: 700-400 = 300
3. P 350: 300-350 = -50 (debet!)
4. W 100: -50+100 = 50
5. P 150: 50-150 = -100 (debet!)
6. W 600: -100+600 = 500
7. P 300: 500-300 = 200
8. P 250: 200-250 = -50 (debet!)
9. W 50: -50+50 = 0
10. P 100: 0-100 = -100 (debet!)
- Debety: 3, 5, 8, 10
- Saldo koncowe: -100
- Max saldo: 700 (po transakcji 1)
